const DiagCatalogEntry kDiagCatalogEN[] = {
  {"E1001", "syntax error: the parser could not match a declaration or statement here", "The grammar expects a specific token at this point; a missing separator, an unbalanced brace, or a misspelled keyword breaks the match, and parsing stops until it is fixed.", {"check the punctuation and keywords around the reported position against LANGUAGE.md §3", "if the message names a token kind, look for a typo just before it", nullptr}, "docs/LANGUAGE.md#3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1002", "source file exceeds the 8 MiB limit", "A single file is capped at 8 MiB so the compiler's memory stays bounded on hostile or runaway input; include expansion is counted separately.", {"split the file into smaller modules", "trim its contents, or move part of it behind a #link", nullptr}, "docs/LANGUAGE.md#2.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1003", "token count exceeds the 2,000,000 limit", "The total token count after include expansion is capped so parse time and memory stay bounded and build time remains answerable from the source tree.", {"split the file or reduce its includes", "move rarely used declarations behind a #link so they are not re-parsed", nullptr}, "docs/LANGUAGE.md#2.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1005", "a double literal must be written as D.D ('.5' is invalid)", "A leading dot is confused with the '.' of field access; requiring D.D keeps the lexer unambiguous.", {"write 0.5 instead of .5", "use `double` for fractional values; keep money in `cost` / int micro-units", nullptr}, "docs/LANGUAGE.md#2.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1006", "amount has more than 6 decimal places (micro-USD limit)", "cost is micro-USD and allows at most 6 decimal places; anything finer cannot be represented and would be silently rounded.", {"round the amount to 6 decimal places", "or express it in micro-USD integers directly", nullptr}, "docs/LANGUAGE.md#4.3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1007", "unterminated string (must be single-line)", "An unterminated or line-broken string swallows the following code, turning one typo into a cascade of unrelated errors.", {"close the string on the same line", "use \\n for a newline, or split the content into multiple segments", nullptr}, "docs/LANGUAGE.md#2.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1008", "invalid string escape or interpolation", "Escapes and interpolation must follow the grammar; a malformed one cannot be decoded, and a line-broken string would swallow the code after it.", {"valid escapes: \\\\ \\\" \\n \\r \\t, and \\u escapes with 4 hex digits", "interpolation must be a plain path such as input.text", nullptr}, "docs/LANGUAGE.md#2.6", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1009", "include path {path} escapes the include root", "Include paths must stay inside the project. A path containing '.' or '..' lets a header reach outside the tree — which breaks reproducible builds (the resolved path depends on where the source tree happens to sit) and makes an offline build read files nobody declared.", {"use a path relative to the include root: {suggestion}", "or add the directory with -I and include it by its name inside that root", nullptr}, "docs/LANGUAGE.md#2.7", {"path", "suggestion", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1010", "#link {spec} is not a valid module name", "A #link payload is a *module name*, not a file name — it resolves to <name>.hbc. Writing a suffix or a path makes people think absolute paths work, and then builds that work on one machine fail on another.", {"write the module name only: #link \"{suggestion}\";", "if the library lives elsewhere, point -L at its directory instead of putting a path in the source", nullptr}, "docs/LANGUAGE.md#2.7", {"spec", "suggestion", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2001", "expected '(' after a type-argument list", "A generic callee written as name<T> must be followed by its call parentheses; leaving them off makes the <T> read as a less-than comparison.", {"write name<T>(...)", "or drop the <T> and let the type be inferred", nullptr}, "docs/LANGUAGE.md#3.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2002", "a workflow name is an identifier, not a quoted string", "Workflow names are identifiers so they can be linked and exported by symbol; a quoted string cannot be a symbol name.", {"write the name without quotes: workflow Name", "if you meant a string value, move it into the body", nullptr}, "docs/LANGUAGE.md#3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2010", "expected ']' after json field access", "Json field access is bracket syntax; a missing ']' leaves the access unterminated and the rest of the expression misparsed.", {"close the access: obj[\"key\"]", "check the key string and its closing bracket", nullptr}, "docs/LANGUAGE.md#4.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2015", "the retry count and delay must be integer literals", "The retry bound is baked into the IR's cost upper bound; a non-literal count or delay cannot be statically bounded, so the strip and trace limits would be wrong.", {"write literal integers: retry 3 times delay 100", "retry bounds are compile-time — a runtime value cannot be used here", nullptr}, "docs/LANGUAGE.md#5.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2016", "tool.call method must be a string literal", "The HTTP method decides idempotency (GET/HEAD are safe to retry); it must be readable at compile time, so a computed method is rejected.", {"pass a literal: tool.call(\"GET\", ...)", "if the method varies, split into separate call sites", nullptr}, "docs/LANGUAGE.md#5.6", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2017", "tool.call method is not a valid HTTP method", "Only the standard methods are recognized; an unknown method cannot be mapped to an idempotency class, so retry safety cannot be proven.", {"use GET, HEAD, POST, PUT, PATCH, or DELETE", "check for a typo or wrong casing", nullptr}, "docs/LANGUAGE.md#5.6", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2018", "an auth clause must be auth env(\"NAME\"): a secret comes only from the environment", "The secret source must be statically auditable; allowing an expression or a default lets the backend start unconfigured and fail only with a 401 at runtime.", {"write auth env(\"NAME\") with a literal variable name", "remove any default — a secret has no safe default", nullptr}, "docs/LANGUAGE.md#8.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3001", "#link {spec} does not resolve: built-in modules are named <std/NAME>", "Angle-bracket links only resolve against the embedded stdlib, which has a fixed, small member list. Anything else must come from a .hbc on the -L path, and that form uses quotes, not angle brackets.", {"use a built-in module: {available}", "or link your own archive by module name: #link \"yourlib\";", nullptr}, "docs/LANGUAGE.md#2.7", {"spec", "available", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3002", "include cycle: {chain}", "Includes are expanded depth-first, so a cycle never terminates — the compiler would keep reopening the same header. Note this is a *module* cycle, not a runtime one: breaking it changes which declarations are visible, not the execution order.", {"move the shared declarations into a third header that both sides include", "or drop one of the two includes if it is only needed for a type that can be forward-declared", nullptr}, "docs/LANGUAGE.md#9.3", {"chain", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3003", "include chain is {depth} levels deep, exceeding the limit of {limit}", "The limit exists so a hostile or accidental chain cannot exhaust the stack. It is far above any readable design — if you hit it, the header layout is the problem, not the limit.", {"flatten the hierarchy: put shared declarations in one leaf header", "or split the deepest header into two that are siblings rather than nested", nullptr}, "docs/LANGUAGE.md#9.3", {"depth", "limit", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3004", "the unit expands to {count} modules, exceeding the limit of {limit}", "Every module is parsed and kept for the whole compile. The cap bounds memory on hostile input and keeps \"how long does this build take\" answerable from the source tree alone.", {"split the unit: move part of it behind a #link so its modules are not re-parsed", "or consolidate small headers that are only ever included together", nullptr}, "docs/LANGUAGE.md#9.3", {"count", "limit", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3005", "a workflow in a header (.h) cannot have a body", "Headers declare interfaces only; a body in a header would be duplicated into every includer, so which implementation runs would depend on the include graph instead of #link.", {"move the body to the matching .hermes implementation", "keep only the signature in the header", nullptr}, "docs/LANGUAGE.md#9.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3009", "a tool declaration field must have the form name = \"value\";", "Tool metadata (endpoint, method, idempotency) is a flat set of string fields; a malformed field means the tool cannot be described to the runtime.", {"write each field as name = \"value\";", "check that the value is a quoted string literal", nullptr}, "docs/LANGUAGE.md#3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3015", "#include {path} targets an implementation file; only .h may be included", "A .hermes file contains bodies. Including one would give every includer its own copy of the implementation and make \"which implementation is linked\" depend on the include graph instead of on #link — which is exactly the property #include/#link separation exists to protect.", {"to use its implementation, write: #link \"{mod}\";", "to use only its types, include its interface: #include \"{name}.h\"", nullptr}, "docs/LANGUAGE.md#2.7", {"path", "mod", "name", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3016", "tool.call needs #link <std/net>; model.generate needs #link <std/model>", "Built-in capabilities are not ambient: the networking and model primitives only exist if the unit links their stdlib module, so an unlinked call has no implementation.", {"add #link <std/net>; for tool.call", "add #link <std/model>; for model.generate", nullptr}, "docs/LANGUAGE.md#2.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3017", "#link is only allowed in .hermes files", "Linking chooses an implementation; headers describe interfaces and are included many times, so a #link there would pull one implementation into every includer.", {"move the #link into the .hermes implementation", "keep only #include in the header", nullptr}, "docs/LANGUAGE.md#9.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3018", "env() arguments must be constant strings: interpolation is not a constant", "A backend endpoint or credential name is read at build time; an interpolated value is only known at runtime, so it cannot be baked into the configuration.", {"pass a plain string literal to env()", "move any interpolation into runtime code instead", nullptr}, "docs/LANGUAGE.md#8.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3019", "a backend address must not carry credentials (user:pass@host)", "Credentials in a URL end up in logs, traces, and the IR; they must come from env() so they are not written into the artifact or leaked.", {"remove user:pass@ from the address", "supply the secret via auth env(\"NAME\")", nullptr}, "docs/LANGUAGE.md#8.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3020", "a header (.h) cannot contain a backend definition", "A backend definition names an address and a secret source — implementation, not interface; putting it in a header gives every includer its own copy.", {"move the backend definition to the .hermes implementation", "keep only a declaration in the header if needed", nullptr}, "docs/LANGUAGE.md#9.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3023", "the input argument must have a type", "input's type is the request contract; without it the decoder has no schema to check the incoming body against.", {"annotate the type: input: Req", "give the struct a matching schema", nullptr}, "docs/LANGUAGE.md#4.8", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3026", "workflow parameters other than \"input\" and \"backend\" are not supported", "A workflow signature is a link-time contract, not a callable interface: there are no cross-workflow calls, so a named parameter has no caller and therefore no source for its value. The host supplies exactly one payload and that payload is `input`; `backend` selects a backend at compile time. Accepting `n: int` would compile and then never run — and the run-time complaint is worded like a compiler bug, hiding a language-design gap behind the compiler's back.", {"put the value in the `input` type and read it as `input.<field>`", "or, if you meant to pick a backend, write `backend = <name of a backend you declared>`", nullptr}, "docs/LANGUAGE.md#3.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3030", "type {type} cannot cross the C ABI boundary", "only int, bool, string, double, cost, and opaque structs have a stable C layout; json, vector<T>, and generics do not", {"use a supported C-ABI type: int, bool, string, double, cost, or an opaque struct", "pass the value inside a struct and cross the boundary by opaque pointer", nullptr}, "docs/LANGUAGE.md#2.7", {"type", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3031", "extern declaration {sym} has no matching #link native", "an extern symbol's implementation must come from a native archive named by #link native; without it the linker cannot resolve the symbol", {"add '#link native \"<archive>\" from \"<header>\";' in the same compilation unit", "make sure the extern symbol name matches a symbol exported by that archive", nullptr}, "docs/LANGUAGE.md#2.7", {"sym", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3032", "native header {header} is not a pure-C ABI header", "cgo only parses C; a C++ header (.hpp/.cpp/.cc) cannot serve as the native contract", {"provide a pure-C header (.h) for the archive", "wrap the C++ API in a thin extern \"C\" shim and point #link native at the .h shim", nullptr}, "docs/LANGUAGE.md#2.7", {"header", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3101", "a compilation unit may contain only one workflow (the rest would be dropped)", "The assembly stage builds IR around a single workflow; an extra one never reaches the output and looks perfectly normal — data silently dropped.", {"split each workflow into its own .hermes file", "build each one separately", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3102", "hermes compile: bare-metal target {target} has no dynamic loader; --link-dynamic is forbidden (got \"{lib}\"). Use --link-static with a pure C/Rust .a.", "A bare-metal artifact is firmware: there is no loader at run time to map a .so/.dylib into the address space, so a shared library in the link line can never be honoured. The plan builder keeps DynamicLibs empty on bare metal for exactly this reason — letting one through would produce an artifact that links but cannot start.", {"replace --link-dynamic with --link-static and give it a pure C/Rust .a", "if the library only exists as .so/.dylib, rebuild it as a static archive first (clang -c, then ar rcs)", nullptr}, "docs/LANGUAGE.md", {"target", "lib", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3103", "hermes compile: \"{lib}\" carries a Go runtime but is not in the g* namespace. Rename it to glibhermesnet.a (or gnet.a) so the target gate can see it; all Go-runtime libraries must start with 'g'.", "The g* prefix is a declaration, not a heuristic scan of file contents: the compiler is entitled to treat every g* library as Go-runtime-bearing, and that naming is the only thing the bare-metal gate reads. A Go archive without the prefix is invisible to the gate, so it can walk a Go runtime into firmware — and the run time would die from the missing OS, not from a build error.", {"rename the archive to glibhermesnet.a (or gnet.a) and rebuild the plan", "if it is really a pure C/Rust library, do not occupy the g* namespace — both sides of the contract are declarations, not scans", nullptr}, "docs/C-ABI.md", {"lib", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3104", "hermes compile: the built-in Go network archive is built for the host and cannot be linked into an artifact cross-compiled to {target}. Build a g* c-archive for {target} and pass it with --link-static, or compile this unit natively.", "A Go c-archive is host-architecture machine code. Cross-compiling the unit to another target while linking the host-built archive produces either unresolved hermes_net_* symbols or an architecture mismatch — and the linker's complaint names a symbol, not the real cause.", {"build the g* c-archive for {target} (GOOS/GOARCH matching the target) and pass it with --link-static", "or drop --target and compile this unit on the host it will run on", nullptr}, "docs/C-ABI.md", {"target", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3105", "hermes compile: {flag} \"{lib}\" is a C++ ABI runtime ({stem}). Hermes links pure C ABI only: name mangling and STL layout are not portable across compilers. Provide a C bridge compiled with extern \"C\" and link that instead.", "Name mangling and STL memory layout are compiler-specific, so a C++ ABI runtime entering the link makes the artifact depend on which compiler built the library. libc++ is licence-legal but still an ABI boundary, which is why this check runs independently of the licence closed set (a licence reason and an ABI reason must not share one code). The supported route is a user-supplied shim with extern \"C\" linkage, which is itself a plain C ABI .a.", {"write a thin shim with extern \"C\" linkage, compile it into a plain .a, and link that instead", "if only an algorithm from the C++ standard library is needed, implement it or pick a pure-C library", nullptr}, "docs/C-ABI.md", {"flag", "lib", "stem", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3106", "hermes compile: bare-metal target {target} may link static .a archives only; --link-static \"{lib}\" is not a static archive. Rebuild it as a pure C/Rust .a.", "On bare metal the plan carries nothing but the static archives you named — no dynamic libraries, no frameworks, no loader. A path that is not a .a (a .so/.dylib, an object file, a directory) has no archive index to resolve hermes_net_* or your extern symbols against, so the link fails with an unresolved symbol far away from the real cause.", {"rebuild it as a pure C/Rust .a (clang -c, then ar rcs)", "or point --link-static at an equivalent library that already ships as an archive", nullptr}, "docs/LANGUAGE.md", {"target", "lib", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3107", "hermes compile: this program calls tools/models and needs the Go network archive; build it with: go build -buildmode=c-archive -o build/glibhermesnet.a ./cmd/hermesnet", "tool.call / model.generate lower to hermes_net_* calls in the generated C, and the only carrier of those symbols is the Go network archive (a c-archive containing the AI interface compatibility layer). With no archive resolved, every one of those calls is an unresolved symbol at link time.", {"run the go build command in the message, or point HERMES_NET_LIB at an existing g* archive (the default lookup is build/glibhermesnet.a)", "if the program needs no network or model access, remove tool.call / model.generate and the backend that needs them", nullptr}, "docs/C-ABI.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3108", "hermes compile: {bad} is a {name} runtime ({licence}): {reason} (source: {source})", "The licence red line is a closed set, checked again on the plan surface as defence in depth: the --link-* inputs were already screened before the plan, but the built-in network archive is a separate input path. A hit means this artifact would statically carry a runtime whose licence forbids distributing it. Which runtime entered the link is the question — not what the symbols look like, since mangling is both a false positive and a false negative.", {"link an equivalent implementation whose licence permits distribution instead", "read the (source: …) URL in the message — the rule names its own authority, and the exception conditions are stated there", nullptr}, "docs/LANGUAGE.md", {"bad", "name", "licence", "reason", "source", nullptr, nullptr, nullptr}},
  {"E3109", "[ERROR] Blocking synchronization or network routing requires a host OS.", "sleep and until need a scheduler and condition variables; a directed emit (route == 2, `to <ctx>`) needs a live context handle to route to. Bare metal has none of these — the slot table is static addresses. Channel routing (route == 1) is deliberately not in this set: it is a compile-time hash plus an integer compare and works on bare metal.", {"replace sleep/until with a counted or polling loop — there is no blocking wait on bare metal", "route the emit by channel instead of `to <ctx>`, or move that workflow to the host side", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3110", "Go runtime libraries (g*) cannot be linked for bare-metal targets. Please use pure C/Rust static libraries.", "A bare-metal artifact runs without an operating system: no scheduler, no threads, no dynamic loader and no syscall layer. A Go runtime archive carries all of those assumptions in its machine code, so the firmware may link and still fail at the first goroutine switch. The g* prefix is the declared carrier of that runtime (legacy Go archive names are screened too), which is why the plan builder refuses the name instead of guessing at symbols.", {"rebuild the network layer as a pure C/Rust static .a exposing an extern \"C\" bridge and link that instead", "or drop --target and compile this unit natively on the host, where the Go runtime is available", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3111", "the --link-* value is not a usable library file on this machine", "The contract of --link-static/--link-dynamic is a library FILE PATH, not a system library name or a linker option. Bare -l<name>, -L<dir>, -Wl,... and any other dash-prefixed value would be forwarded to the linker as-is, which lets a library the plan never saw enter the artifact — and the product-side gate cannot see static archives at all.", {"pass an existing .a / .so / .so.N / .dylib file on this machine", "or drop the flag if the library is already found by the compiler driver", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4116", "a contract clause must be a boolean predicate", "A clause decides whether the call may proceed (require) or whether the result is acceptable (ensure). A non-boolean value has no such meaning, and the language has no truthiness rule to borrow one from.", {"compare explicitly, e.g. require(x > 0)", "or remove the clause if it is not a condition", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4117", "`result` is only meaningful in `ensure`, not in `require`", "require runs before the call, so there is no return value to talk about. Binding `result` there would silently mean `undefined`, which is worse than refusing.", {"drop `result` from this require", "or move the condition into an ensure", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4118", "a contract clause calls something that may have side effects", "A clause is evaluated on entry or on return and its failure is reported as ContractError. A call with side effects would run them as a side effect of checking, and could fail for a reason that has nothing to do with the contract.", {"rephrase the clause over the parameters and `result` only", "or move the call into the body and store its outcome in a variable first", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4119", "a contract clause belongs in the signature, not inside the body", "require / ensure are part of the declaration: they are checked on entry and on return, so they cannot sit among the statements where control flow would decide whether they run at all.", {"move the clause up between the parameter list and `entry` / `-> T`", "or write a plain `if` statement if you really want a body-level check", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4120", "contract clauses on functions are not supported yet (2.0.1); they work on workflows", "D-036 allows a clause on a workflow or on a function. A function body is inlined at each call site, so a clause there has to be expanded at every inlining point; that part is not implemented. Refusing is deliberate: ignoring the clause would silently drop a promise the author wrote down.", {"put the clause on the workflow, or check the condition with an `if` inside the function body", "or record the gap if you genuinely need function-level contracts", nullptr}, "docs/LANGUAGE.md#39-契约子句require--ensured036201", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4002", "this catch is unreachable: an earlier catch (Error e) already catches everything", "Catch arms are tried in order; a catch (Error) before a narrower catch swallows every error, so the later arm can never run.", {"move the broad catch (Error) to the end", "or remove the unreachable arm", nullptr}, "docs/LANGUAGE.md#5.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4005", "cost cannot be added to or subtracted by a bare int", "cost is micro-USD; adding a bare int treats that int as micro-USD by accident, a unit error that silently changes money by a factor of 10^6.", {"wrap the int as a cost explicitly", "or keep the amount in one unit throughout", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4006", "int and double do not auto-promote", "There is no implicit numeric promotion; automatic int to double is the classic source of silent precision loss and rounding bugs.", {"convert explicitly to the type you want", "or keep both operands the same type", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4007", "an arithmetic operator was applied to a non-numeric operand (string, bool, json)", "Strings have no arithmetic and there is no operator overloading; concatenation is deliberately disallowed because it hides encoding and locale, and unary minus is only defined on numbers.", {"combine strings with interpolation (put the value inside the string) instead of an operator", "narrow json to a numeric type before arithmetic (json.as_int)", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4008", "cost and double do not mix in arithmetic", "cost is integer micro-USD; mixing it with a double reintroduces the exact rounding error cost was designed to avoid.", {"keep money math in cost (integers)", "or convert deliberately and round explicitly", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4009", "operator % requires int operands", "Remainder is only meaningful on integers; a remainder on cost, double, string, json, or struct has no well-defined result.", {"use int operands for %", "for cost, work in micro-USD ints first", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4010", "cannot compare two values of different types with == or !=", "Equality requires both operands to be the same type; comparing across types has no single meaning and would need a hidden coercion.", {"compare values of the same type", "convert one side explicitly to match", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4011", "cannot order-compare these operand types", "Ordering (< <= > >=) is only defined for int, double, cost, and string; bool, json, and struct have no total order.", {"compare only int, double, cost, or string", "for json, compare a specific extracted field", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4012", "logical &&, ||, and ! require bool operands", "The language has no truthiness; &&, ||, ! are boolean connectives, so an int/string/json operand would need an implicit nonzero-means-true rule that does not exist.", {"compare explicitly: x != 0, or s != a quoted empty string", "or change the operand to a bool", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4014", "duplicate struct declaration in this file", "Each struct name maps to one layout; a second declaration in the same file makes the type ambiguous and the field order depend on which one wins.", {"rename one of the two structs", "or remove the duplicate if it is a leftover", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4016", "the type has no such field", "Field access reads a slot at a fixed offset; a field the type does not declare would read bytes that were never laid out, so the access cannot be compiled.", {"use one of the type's declared fields", "or add the field to the struct declaration", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4018", "`match` has no `default` branch", "Exhaustiveness cannot be proven for string subjects, so a match without default would have an undefined result for an unmatched value.", {"add a default: arm", "or narrow the subject so the cases are provably exhaustive", nullptr}, "docs/LANGUAGE.md#5.3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4019", "a `case` label has a different type than the `match` subject", "Case labels are compared to the subject; an int label on a string subject (or vice versa) can never match and signals a type confusion.", {"make the label the same type as the subject", "or convert the subject before matching", nullptr}, "docs/LANGUAGE.md#5.3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4020", "the same case label appears more than once", "A duplicated label makes the second arm dead and hides that the author probably meant a different value.", {"remove the duplicate arm", "or change it to the value you actually meant", nullptr}, "docs/LANGUAGE.md#5.3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4021", "return type mismatch: the returned value does not match the declared return type", "The declared return type is the workflow's contract — callers, the linker, and the IR schema all rely on it; a different value breaks all of them.", {"return a value of the declared type", "or change the declaration to the type you return", nullptr}, "docs/LANGUAGE.md#3.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4022", "cannot return a tuple", "A workflow's return type must be a single named type with a schema; a tuple has no name, so it cannot be exported or described to callers.", {"wrap the values in a struct and return that", "or return one value and pass the rest via input", nullptr}, "docs/LANGUAGE.md#3.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4023", "cannot bind the error object to a variable", "The catch error object lives only inside its catch block and is borrowed, not owned; binding it out would let it outlive the error it points to.", {"use the error object inline inside the catch block", "if you need its data later, copy the fields out explicitly", nullptr}, "docs/LANGUAGE.md#5.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4024", "`unlimited` is not a value: it may only appear as max_steps = unlimited", "`unlimited` means no compile-time upper bound; it is a bound marker, not a constant. Allowing it in a value position would create a variable with no value and break every bound.", {"use unlimited only in model.agent(max_steps = unlimited)", "assign a concrete value elsewhere", nullptr}, "docs/LANGUAGE.md#6.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4025", "fallback return type does not match the main expression", "The fallback is the value used when the main expression raises; if its type differs, callers would get one of two incompatible types at runtime.", {"make the fallback return the same type as the main expression", "or convert the fallback value to that type", nullptr}, "docs/LANGUAGE.md#5.4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4026", "cannot reassign a const variable inside a fallback block", "A const is immutable for the whole scope; a fallback is not an exception — reassigning there would make const mean different things in different blocks.", {"use a non-const variable if it must change", "or move the assignment out of the fallback", nullptr}, "docs/LANGUAGE.md#5.4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4027", "an if/while condition must be bool", "A condition is a control-flow branch point and the language has no truthiness; int/string/json/cost have no notion of being true, so an implicit rule would be undefined at runtime.", {"compare explicitly: x != 0, or s != a quoted empty string", "or produce a bool from the expression", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4028", "the loop variable of a `for` loop is used after the loop has ended", "The loop variable is owned by the for header and exists only inside the body; its slot is reclaimed when the loop ends, so referencing it outside reads a variable that no longer exists.", {"move the use inside the loop body", "or copy the value to a variable declared before the loop", nullptr}, "docs/LANGUAGE.md#3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4029", "legacy float label has no IR value representation", "This is a legacy-tag defense line, not a ban on floating point. Since v2.0.0 the only floating type is `double` (IEEE-754 binary64) and literals are emitted as the bit pattern {{\"k\":\"double\",\"bits\":\"<16 lowercase hex digits>\"}}; IR bytes contain no JSON floating-point numbers, so V-7 / canonical / signing all hold. A LitExpr tagged \"float\" is the pre-v2.0.0 shape: it falls into the string fallback and produces {{\"t\":\"string\",\"v\":\"float\"}} — valid IR that silently returns the string \"float\" at runtime. The three scanners stay as defense in depth against C ABI callers that ignore diagnostics.", {"use `double` for floating-point values (literals 1.5 / 1.5e2 / 1e3 are supported)", "keep money in `cost` / int micro-units; the `json.as_float` API name is unchanged", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4030", "argument type mismatch in a call", "A call passes a value of one type where the callee declares another; with no implicit conversion, the call cannot be compiled to the declared signature.", {"pass a value of the declared parameter type", "or convert the argument explicitly", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4031", "an array index must be an integer", "Array indexing is an integer offset; a non-int index has no defined position and would need a hidden truncation.", {"use an int index", "or convert the index to int explicitly", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4032", "cannot index a value that is not an array", "Only arrays support indexed access; indexing an int/string/json/struct has no element to return.", {"index an array value", "for json, extract a typed array first (json.as_array)", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4033", "cannot compare two doubles with == or !=", "Exact equality on binary floating point is not a stable predicate, so it cannot be proven at compile time and is rejected instead of silently returning false. Rounding makes two mathematically equal values compare unequal, and NaN is unequal to itself: `x == x` can be false, and `x != x` quietly becomes the only NaN test in the language.", {"keep the value in exact units (int micro-units, or `cost`) and compare that", "or compare with an explicit tolerance: use a `double` literal or a value from the input, e.g. `json.as_float(input.eps)`; equality itself is still rejected", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4034", "this error field is specified but the runtime does not produce it yet", "LANGUAGE.md 7.1.1 declares the field, so it is not a spelling mistake — but the executor's error value does not carry it yet. Accepting the access would compile and then die at run time with `field does not exist`, which is a plain error and cannot be caught: a static checker that passes while the program fails is worse than a refusal.", {"read a field the runtime already carries (E4016's help lists them per error type)", "or read the outcome as a normal value: with `allow_status = [404]` the status comes back on HttpResult<T>, so `r.status == 404` needs no error object at all", nullptr}, "docs/LANGUAGE.md#7.1.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4035", "a backend parameter default must be a bare backend name", "A parameter default becomes `params[].v`, a constant folded at compile time — so `backend = 1 + 1` has no value to record, because there is no evaluator at run time. And which backend is used is read **only** from a bare identifier: `backend = \"homonoia\"` folds into {{\"k\":\"string\",\"v\":\"homonoia\"}} and still leaves the backend name empty, so the next error the user sees is about something else entirely. A dotted name is worse — it folds to its **last** segment and silently selects a different backend.", {"write the backend bare and unquoted: `backend = homonoia`", "or omit the parameter entirely: a workflow without it simply has no default backend", nullptr}, "docs/LANGUAGE.md#3.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3027", "#bind is only allowed in .hermes files", "#bind names who **provides** the implementation. A .h says what things look like, never who supplies them: putting #bind in a header would let every includer inherit an implementation choice they never made, and the same type would resolve to different providers in different units.", {"move the #bind line into the matching .hermes", "keep the .h to declarations only (struct / extern / workflow signatures)", nullptr}, "docs/LANGUAGE.md#3.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3028", "#bind must be at the top level of a file", "A directive is not a statement. #bind decides which implementation the whole unit links against, so it has to be settled before any body is parsed — inside a workflow or a function there is no module boundary for it to apply to.", {"move the #bind line to the top of the file, above any workflow or function", "or delete it from the body: a body cannot choose its own provider", nullptr}, "docs/LANGUAGE.md#2.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4036", "#bind does not introduce names: {name} is not declared", "#bind decides **who supplies the implementation**, not **which names you can see**. Those are two different questions and Hermes refuses to bind them to one string: the provider edge carries an identity and a hash, while visibility is what #include brings in.", {"add the include that declares it: #include \"{header}\"", "or spell the fully-qualified declaration in a .h and include that", nullptr}, "docs/LANGUAGE.md#3.5", {"name", "header", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4101", "a void call cannot be used as a value", "`void` means this call returns nothing: there is no value to store, pass or compare, so a value position (a binding, an argument, one side of an operator) has nothing to put there. Letting it through leaves a hole that only surfaces when the IR is assembled, and that error names a missing node field instead of `this call returns nothing`.", {"call it as its own statement and drop the binding", "if you need an outcome from it, give the callee a return type — `void` is a statement, never an operand", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4102", "{fn} takes a snapshot, got {got}", "A snapshot is the opaque handle returned by memory.checkpoint(): it is a transaction boundary, not a value. Anything else (a json value, an int, a struct) is not a boundary, so committing it would silently do nothing. Snapshot is a separate type rather than json on purpose — it cannot enter json and cannot be passed across a workflow.", {"pass the value you got from memory.checkpoint()", "keep that handle in a local variable between checkpoint() and rollback()/commit() — it is opaque, so it cannot be stored in json or handed to another workflow", nullptr}, "docs/LANGUAGE.md", {"fn", "got", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4103", "a void call cannot be returned", "Returning `void` would hand the caller a value that does not exist. The declared return type is the workflow's contract, so there is nothing to write into the return slot.", {"write the call on its own line", "then `return` a value of the declared return type", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4104", "this workflow must return a value", "The declared return type is not void, so a bare `return;` leaves the epilogue without a value and the backend would emit a `ret` with an undefined result. A body-level `return` in a workflow is exactly the value the caller receives.", {"return a value of the declared type", "or declare the workflow's return type as void and drop the value from every other `return`", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4105", "break outside a loop", "`break` leaves the innermost loop, and the checker only counts for/while bodies as loops — here there is nothing to leave. Crossing the workflow boundary is what `stop` exists for; mixing the two makes the control flow unreadable.", {"use `workflow.stop(reason: …)` to end the workflow early", "or move the `break` inside the loop it is meant to leave", nullptr}, "docs/LANGUAGE.md#3.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4106", "continue outside a loop", "`continue` jumps to the next iteration of the innermost loop. With no loop around it there is no target, so the statement would be a no-op that looks like control flow.", {"move it inside the loop it is meant to continue", "or delete it — nothing is being continued here", nullptr}, "docs/LANGUAGE.md#3.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4107", "stop outside a workflow", "`stop` ends the current workflow and writes its data into the return slot. At declaration level there is no workflow to end: the checker only enters workflow bodies.", {"move it inside a workflow body", "if this is top-level initialisation, there is nothing to stop — delete it", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4108", "stop data does not match the workflow return type", "`workflow.stop` returns its data to the caller, so the data has to be the type the workflow declares. Stop writes straight into the return slot, so a mismatch is a `ret` of the wrong type: it compiles and the caller reads garbage.", {"pass a value of the declared return type", "or change the workflow's declared return type to the type you pass", nullptr}, "docs/LANGUAGE.md#3.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4109", "undeclared signal `{sig}`", "Signals are a closed set, declared with `export signal <Name>;`. The same code is emitted by all three uses, worded `handler for undeclared signal`, `wait for undeclared signal` and `emit of undeclared signal`, because they are one fact: the name is not in the declared set, so it can only be a typo. A handler for it waits forever, a wait on it blocks until its timeout every time, and an emit of it fires into nothing without reporting anything.", {"declare it with `export signal <Name>;`", "or check the spelling — the name must match a declared signal exactly", nullptr}, "docs/LANGUAGE.md", {"sig", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4110", "duplicate handler for `{sig}` in the same scope", "Handlers are collected per scope. Two for one signal in one scope would both be candidates, and which one runs is decided by binding order — that is not something a reader can see, so the program's behaviour would depend on an invisible ordering.", {"merge the two handlers into one", "or move one into a nested block — the list is per scope, so a nested scope may declare its own", nullptr}, "docs/LANGUAGE.md", {"sig", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4111", "sleep takes a duration", "The duration is a number of milliseconds, or a literal with a unit that the parser already folded; anything else has no meaning to the runtime and would be silently coerced. The same code fires for `until` with `timeout takes milliseconds as an int`: the timeout is compared against the monotonic clock in milliseconds, and a string or a struct cannot be a deadline.", {"pass an int (ms) or a literal with a unit, e.g. sleep(1500) or sleep(1.5s)", "for a timeout, pass an int of milliseconds: timeout(30000) or timeout(30s)", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E5002", "a value declared inside a `parallel` block is not visible outside it", "Each branch of parallel runs concurrently; a value produced inside the block has no single well-defined value outside, so it is scoped to the block.", {"use the value inside the parallel block", "or return it from the branch and merge the results", nullptr}, "docs/LANGUAGE.md#5.2", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E5007", "a tool call inside `retry` has no idempotency proof", "A retry re-runs its whole body on a RunError; a call_tool without an idempotency proof repeats the same POST — duplicate charges, duplicate side effects.", {"move the call outside the retry subtree", "or give the tool a real proof (GET/HEAD, idempotent = true, or a pure idem_key)", nullptr}, "docs/LANGUAGE.md#5.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E5009", "idempotency key must be derived from the input", "An idem key that is constant or random is not idempotent: a constant key collapses distinct requests, a random one changes every retry and defeats dedup.", {"derive the key from request fields (e.g. the order id)", "or omit idem_key if the tool is idempotent another way", nullptr}, "docs/LANGUAGE.md#5.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E5010", "cannot write to an outer variable inside `parallel`", "Parallel branches run concurrently; writing a variable declared outside the block is a data race whose result depends on scheduling, so it is rejected.", {"return a value from each branch and merge after parallel", "or use a variable declared inside the branch", nullptr}, "docs/LANGUAGE.md#5.2", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_ASSIGN_IMMUTABLE", "Cannot mutate const variable", "A `decl` node with const:true (IR.md §4.2) means the binding never changes; only variables declared with `auto` may be assigned. The check runs at assembly time, not at run time: catching it later would mean a wrong program compiles and only fails when that line is reached. It is one of the few load-time diagnostics the user can actually fix, which is why the assembly stage reports it as a user error rather than a compiler bug.", {"remove `const`, or assign to a new variable instead", "if this IR was not produced by `hermes ir`, regenerate it — a const `decl` followed by an `assign` to it can only come from a hand edit", nullptr}, "docs/IR.md#4.2", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_BAD_LOC", "{what}: loc.m={m}, but the unit has only {count} module(s) (0..{last})", "loc.m indexes unit.modules[]. An out-of-range value crashes the diagnostic renderer itself — the loader would fail while trying to report a failure, and you would see a panic instead of this message.", {"fix loc.m in the producer — this is almost always a frontend bug, not hand-edited IR", "or regenerate the IR if it was edited by hand", nullptr}, "docs/LANGUAGE.md", {"what", "m", "count", "last", nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_BAD_ROOT", "workflow {wf}: root={root}, but {reason}", "The executor starts at root and expects a statement list there, i.e. a node with k=\"seq\". Any other kind has no defined entry semantics, so the first step of the run would be undefined.", {"point root at the first `seq` node", "or wrap the body in a `seq` node if the workflow has a single statement", nullptr}, "docs/LANGUAGE.md", {"wf", "root", "reason", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_CODEGEN", "code generation failed: the workflow could not be lowered to IR", "Codegen rejects shapes it cannot lower faithfully (for example an if/return decision tree that does not match its expected form); emitting a wrong IR would be worse than failing.", {"fix the construct the message names", "or report it — an internal codegen error is a compiler bug, not your input", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_CYCLE", "workflow {wf}: the node graph has a cycle — {chain}", "The IR must be a DAG (IR.md V-3). With a cycle the executor can re-enter the same node forever, so neither a deadline nor a budget can bound the run — it would be killed from outside instead of stopping itself.", {"break the cycle by removing the edge {edge}", "if you need repetition, use `retry` — it is bounded, and the graph itself must stay acyclic", nullptr}, "docs/LANGUAGE.md", {"wf", "chain", "edge", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_DANGLING_REF", "{what} points at {id}, but {table} has {range}", "Every id in the IR's reference positions must index into the table it names. A dangling id means the IR was truncated, hand-edited, or produced by a frontend that is one version out of step.", {"remove the reference at {path}", "or add the missing entry — the table must stay consistent with its references", nullptr}, "docs/LANGUAGE.md", {"what", "id", "table", "range", "path", nullptr, nullptr, nullptr}},
  {"E_IR_DUP_ID", "duplicate node id {id} in workflow {wf}: first at {first}, again at {second}", "Node ids are array indices (IR.md §4). Two nodes sharing one id make every reference to it ambiguous — a kid that says {id} could mean either of them, and which one you get depends on traversal order.", {"renumber the node at {second} (ids must stay contiguous, 0..{last})", "or delete one of the two nodes if it is a leftover", nullptr}, "docs/LANGUAGE.md", {"id", "wf", "first", "second", "last", nullptr, nullptr, nullptr}},
  {"E_IR_DYNAMIC_CALL", "non-recursive function {fn} is called through call_fn at {where}: compiled mode must inline it", "Hermes is a compiled language: non-recursive functions are expanded at compile time so the runtime has no dynamic dispatch. A call_fn to a non-recursive function means the IR came from an older compiler, was hand-edited, or codegen has a bug. Allowing it would silently reintroduce dynamic dispatch exactly where the bounds are supposed to be static.", {"rebuild the IR with the current compiler (non-recursive calls are inlined)", "if {fn} really recurses, mark it recursive — the depth limit 512 is the only runtime guard", nullptr}, "docs/LANGUAGE.md", {"fn", "where", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_ENTRY", "{reason} (workflow {name})", "Entry selection must be unambiguous: `hermes run` without --workflow picks the single exported entry. Zero candidates means there is nothing to run; two means the choice is a coin flip and the artifact is not reproducible.", {"mark exactly one exported workflow with `entry`", "or pass --workflow <name> explicitly at run time", nullptr}, "docs/LANGUAGE.md", {"reason", "name", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_EXPORT_MISMATCH", "workflow {name} has exported={exported}, but {where} {verb} it", "`exported` on the workflow and exports.workflows (the symbol table) are two representations of one fact. The stripper reads the scalar; the linker reads the table. When they disagree, one believes the symbol is reachable and the other believes it does not exist — the artifact then works or breaks depending on which tool ran first.", {"set exported={want} on the workflow", "or {action} \"{name}\" {target}", nullptr}, "docs/LANGUAGE.md", {"name", "exported", "where", "verb", "want", "action", "target", nullptr}},
  {"E_IR_FLOAT", "IR contains a floating-point JSON number at {path} (starts with {preview})", "Canonical JSON forbids floats (IR.md P-1). The shortest round-trip representation of a float differs between Go, Rust and C++, so a float anywhere in the hashed bytes makes cross-language verification fail at random, and only on some machines.", {"encode it as a string: {{\"k\":\"double\",\"bits\":\"3ff8000000000000\"}}", "money and probabilities are integers — use micro-USD (1e-6) and basis points (1e-4)", nullptr}, "docs/LANGUAGE.md", {"path", "preview", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_LOAD_FAILED", "the IR bytes are not well-formed JSON for this schema: {detail}", "The loader decodes into a fixed shape. When a field has the wrong JSON type (an object where an integer was expected, a string where a list was expected), decoding stops at the first mismatch and nothing after it is checked — so this is the only diagnostic you get until it is fixed.", {"fix the reported field; the surrounding IR is probably fine", "or regenerate the artifact if it was hand-edited", nullptr}, "docs/LANGUAGE.md", {"detail", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_RECOMPUTE_DRIFT", "{field} says {claimed}, but recomputing from the IR gives {actual}", "This field is derived, not authoritative. It is written at build time and must be recomputed on load — otherwise a tampered value would silently raise the execution ceiling, and bounds exist precisely to cap what a run may do.", {"regenerate the artifact — the producer wrote an inconsistent value", "if it was edited by hand, do not: derived fields are recomputed, not trusted", nullptr}, "docs/LANGUAGE.md", {"field", "claimed", "actual", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_RETRY_UNPROVEN", "retry node {retry} can execute call_tool {call} more than once, but tool {tool} declares idem.mode={mode} — there is no idempotency proof", "A retry re-runs its whole body whenever a RunError comes back. If that body contains a tool call without a proof of idempotency, every 5xx repeats the same POST: duplicate charges, duplicate side effects. E5007 is a compile-time gate on the source AST, so it cannot protect an IR file that was hand-edited, produced by an older compiler, or rearranged by a codegen bug. This check runs on the node graph at load time, where 'inside retry' means reachable from retry.body.", {"move call_tool {call} out of the retry subtree — keep only proven calls inside it", "give {tool} a real proof (GET/HEAD, idempotent = true, or a pure idem_key) and rebuild the IR with hermes ir; do not hand-edit idem.mode", nullptr}, "docs/LANGUAGE.md", {"retry", "call", "tool", "mode", nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_SCHEMA_UNSTABLE", "schema at {path} does not re-canonicalise to the same bytes: {detail}", "schemas[].json is embedded verbatim and participates in the type hash. If re-encoding changes even one byte, an offline build and a signature check disagree about which schema was signed.", {"emit the schema with keys in byte order and no whitespace", "or report the frontend that produced it — this is normally a codegen bug", nullptr}, "docs/LANGUAGE.md", {"path", "detail", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_SYM_CONFLICT", "symbol {name} appears {count} times in {namespace}: {places}", "Each of the four namespaces (type / workflow / backend / tool) must hold unique names. With duplicates, export lookup becomes order-dependent — the linker resolves whichever it scans first, so the same archive can link differently on two machines.", {"rename one of them", "or drop the duplicate export if it is a leftover", nullptr}, "docs/LANGUAGE.md", {"name", "count", "namespace", "places", nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_VAR_MISMATCH", "var {name} (id {var}) and the `decl` node binding it disagree: {detail}", "vars[] and decl nodes are two views of one binding. The executor reserves the slot from vars[] but assigns it in the decl node; if they disagree, the variable is read from a slot that was never written.", {"make var {var}.decl point at the `decl` node that assigns it", "or drop the vars[] entry if the decl node no longer exists", nullptr}, "docs/LANGUAGE.md", {"name", "var", "detail", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_VERSION", "{field} is {got}, but this build only accepts {want} (Hermes 2.0.0 and later)", "IR is deliberately not forward-compatible: 2.x reads only what 2.0.0 and later produce. Accepting an older artifact would mean interpreting fields whose meaning has changed since — a wrong answer that looks like a right one. There is no migration path on purpose: 1.x artifacts are rejected loudly instead of being silently misread.", {"recompile the source with this compiler (2.0.0+)", "if you must run a 1.x artifact, use a 1.x binary — do not hand-edit the version field", nullptr}, "docs/LANGUAGE.md", {"field", "got", "want", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W2003", "#link does not need a trailing semicolon (like #include)", "A directive is not a statement: #include and #link both end at the line end, so a trailing ';' is stray.", {"remove the trailing ';'", "leave the directive as #link <std/net>", nullptr}, "docs/LANGUAGE.md#2.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W2004", "max_steps = unlimited: this agent has no statically known upper bound on steps", "With unlimited steps, max_spans is no longer a provable trace bound and budgets cannot be pre-reserved; only the runtime step cap remains.", {"set a concrete max_steps if you need provable bounds", "accept it only when the runtime cap is the intended guard", nullptr}, "docs/LANGUAGE.md#6.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W4112", "no handler for signal `{sig}` on channel \"{chan}\"", "The channel is hashed at compile time, so a typo produces a hash that nothing listens on: the emit runs and does nothing, silently. A global emit matches any global slot; a channel-routed emit only matches a slot on that same channel.", {"check the channel name, or add a handler: on {sig} from \"{chan}\" {{ … }}", "if another module handles it, ignore this warning.", nullptr}, "docs/LANGUAGE.md", {"sig", "chan", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W4113", "until without a timeout can block forever", "The workflow's bounds are step counts, not wall-clock time. An until with no timeout has no upper bound the compiler can see, so one missing emit hangs the artifact while the cost model still reports a finite run.", {"add a bound: until(<Signal>) timeout(30s)", "if the wait is genuinely meant to be unbounded, keep it and make sure an emit is guaranteed.", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W5004", "a struct field named like a status code is compared with an HTTP status, but the default tool.call contract never binds it for a non-2xx response", "Without allow_status, tool.call returns T only on success and throws HttpError otherwise, so on a 404 the flow leaves at the tool.call line and the field is never bound — the comparison can never be true. The HTTP status only reaches the call site through allow_status (HttpResult<T>.status). This is a heuristic warning, not an error: a business field that happens to be named status and really equals 404 is legal, and the compiler cannot tell the two apart (LANGUAGE.md 12.1 L3).", {"list the code in the call's allow_status and compare the result's status: `tool.call<T>(..., allow_status = [404])` then `r.status == 404`", "or read the outcome from the response body instead: a 200 response carries T, so check a business field on T (e.g. `found = false`) rather than the HTTP status", nullptr}, "docs/LANGUAGE.md#12.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W5005", "entry has no structural contract: input is declared as json, so hermes serve cannot generate documentation from it nor reject malformed requests at the entry point", "The input type is the HTTP request contract. When declared as json the request body is arbitrary JSON, so serve can neither generate an API schema nor validate the fields at the entry point. This is a sanctioned escape hatch (LANGUAGE.md §4.8), but it loses compile-time contract protection.", {"declare a struct as the contract: `input: SupportInput`, where the fields are the shape of the request body and non-`T?` fields become required", "if arbitrary JSON is truly needed, keep json but accept this warning, or upgrade it to an error with --deny-warnings", nullptr}, "docs/LANGUAGE.md#4.8", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W_IR_PANEL_TRUNCATED", "stopped after {shown} diagnostics; {dropped} more were suppressed", "A single bad input can produce thousands of follow-on errors, and the useful ones are always at the top. The cap keeps the report readable and bounds memory on hostile IR.", {"fix the first {shown} and re-run — the rest are usually consequences", "or raise the cap with --max-diags if you really want the full list", nullptr}, "docs/LANGUAGE.md", {"shown", "dropped", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
};
