const DiagCatalogEntry kDiagCatalogZH[] = {
  {"E1001", "语法错误：解析器在这里无法匹配任何声明或语句", "语法在此处要求特定记号；缺分隔符、括号不配对或拼错关键字都会打断匹配，在修好前解析无法继续。", {"对照 LANGUAGE.md §3 检查报错位置前后的标点与关键字", "若消息点了记号种类，留意它前面是否有拼写错误", nullptr}, "docs/LANGUAGE.md#3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4116", "契约子句必须是布尔判据", "子句决定这次调用能不能进行（require）或返回值可不可接受（ensure）。非布尔值没有这个含义，而语言没有真值判断可以让它借用。", {"显式比较，例如 require(x > 0)", "或者如果它不是条件，就删掉这条子句", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4117", "`result` 只在 `ensure` 里有意义，不能在 `require` 里用", "`require` 在调用之前运行，此时还没有返回值可谈。在那里绑定 `result` 只会默默等于「未定义」，那比直接拒绝更糟。", {"把 `result` 从这条 require 里去掉", "或者把这条条件挪进 ensure", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4118", "契约子句调用了可能有副作用的东西", "子句在入口或返回时求值，失败会报成 ContractError。带副作用的调用会把这些副作用当成「检查的副产物」执行掉，而且可能因为与契约无关的原因失败。", {"把子句改写成只依赖形参与 `result`", "或者把调用挪进体内，先把结果存进变量", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4119", "契约子句属于签名区，不能写在体内", "require / ensure 是声明的一部分：它们在入口与返回时检查，因此不能待在语句中间——那里的控制流会决定它们到底跑不跑。", {"把子句挪到参数列表与 `entry` / `-> T` 之间", "或者如果你确实要一条体内检查，写普通的 `if` 语句", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1002", "源文件超过 8 MiB 上限", "单个文件被限制在 8 MiB，好让编译器在恶意或失控输入下内存有界；include 展开另行计数。", {"把文件拆成更小的模块", "精简内容，或把一部分挪到 #link 后面", nullptr}, "docs/LANGUAGE.md#2.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1003", "token 数超过 2,000,000 上限", "include 展开后的总 token 数被限制，好让解析时间与内存有界、构建耗时能从源码树本身回答。", {"拆分文件或减少 include", "把不常用的声明挪到 #link 后面，避免被重新解析", nullptr}, "docs/LANGUAGE.md#2.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1005", "double 字面量必须写成 D.D（'.5' 非法）", "前导点会与字段访问的 '.' 混淆；要求写成 D.D 才能让词法无歧义。", {"写成 0.5 而不是 .5", "小数用 `double`；金额仍留在 `cost` / int 微单位", nullptr}, "docs/LANGUAGE.md#2.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1006", "金额超过 6 位小数（微美元上限）", "cost 是微美元，最多保留 6 位小数；更细的精度无法表示，只会被静默舍入。", {"把金额四舍五入到 6 位小数", "或者直接用微美元整数表示", nullptr}, "docs/LANGUAGE.md#4.3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1007", "字符串未闭合（必须单行）", "未闭合或跨行的字符串会把后面的代码吞进去，一个笔误变成一串不相关的错误。", {"在同一行内闭合字符串", "用 \\n 表示换行，或把内容拆成多段", nullptr}, "docs/LANGUAGE.md#2.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1008", "非法的字符串转义或插值", "转义与插值必须符合语法；写坏了一个就解码不出来，跨行的字符串还会吞掉后面的代码。", {"合法转义：\\\\ \\\" \\n \\r \\t，以及带 4 位十六进制的 \\u 转义", "插值必须是纯路径，如 input.text", nullptr}, "docs/LANGUAGE.md#2.6", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1009", "include 路径 {path} 逃出了 include 根目录", "include 路径必须留在项目内。含 '.' 或 '..' 的路径能让头文件伸到源码树外面 —— 这会破坏可重现构建（解析结果取决于源码树恰好放在哪），也让离线构建去读没人声明过的文件。", {"用相对 include 根的路径：{suggestion}", "或者用 -I 把那个目录加进来，再按它在那个根内的名字 include", nullptr}, "docs/LANGUAGE.md#2.7", {"path", "suggestion", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E1010", "#link {spec} 不是合法的模块名", "#link 的载荷是**模块名**不是文件名 —— 它解析成 <name>.hbc。写后缀或路径会让人以为绝对路径可行，然后一台机器上能过的构建在另一台上失败。", {"只写模块名：#link \"{suggestion}\";", "库在别处的话，把 -L 指向它的目录，而不是把路径写进源码", nullptr}, "docs/LANGUAGE.md#2.7", {"spec", "suggestion", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2001", "类型实参列表后缺少 '('", "写成 name<T> 的泛型调用必须紧跟调用括号；省掉会让 <T> 被当成小于比较。", {"写成 name<T>(...)", "或者去掉 <T>，让类型被推断", nullptr}, "docs/LANGUAGE.md#3.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2002", "workflow 名是标识符，不是带引号的字符串", "workflow 名是标识符，才能按符号被链接与导出；字符串不能充当符号名。", {"去掉引号：workflow Name", "如果你要的是字符串值，把它放进函数体", nullptr}, "docs/LANGUAGE.md#3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2010", "json 字段访问后缺少 ']'", "json 字段访问是方括号语法；缺 ']' 会让访问没闭合、后面的表达式被误解析。", {"闭合访问：obj[\"key\"]", "检查键字符串与它的右括号", nullptr}, "docs/LANGUAGE.md#4.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2015", "retry 次数与 delay 必须是整数字面量", "retry 上界会写进 IR 的代价上界；非字面量的次数或延迟无法静态定界，剥离与 trace 限额都会算错。", {"写成整数字面量：retry 3 times delay 100", "retry 上界是编译期的，这里不能用运行期的值", nullptr}, "docs/LANGUAGE.md#5.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2016", "tool.call 的 method 必须是字符串字面量", "HTTP 方法决定幂等性（GET/HEAD 可安全重试）；它必须在编译期可读，所以拒绝计算出来的方法。", {"传字面量：tool.call(\"GET\", ...)", "方法若会变，拆成几个独立调用点", nullptr}, "docs/LANGUAGE.md#5.6", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2017", "tool.call 的 method 不是合法的 HTTP 方法", "只识别标准方法；未知方法无法归入幂等类别，重试安全性就无法证明。", {"用 GET、HEAD、POST、PUT、PATCH 或 DELETE", "检查是否拼错或大小写不对", nullptr}, "docs/LANGUAGE.md#5.6", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E2018", "auth 子句必须是 auth env(\"NAME\")：密钥只能来自环境", "密钥来源必须可静态审计；允许表达式或默认值会让后端在未配置时启动，只在运行期以 401 失败。", {"写成 auth env(\"NAME\")，变量名用字面量", "去掉任何默认值——密钥没有安全的默认", nullptr}, "docs/LANGUAGE.md#8.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3001", "#link {spec} 无法解析：内置模块的名字是 <std/NAME>", "尖括号形式的链接只在内嵌 stdlib 里解析，而它的成员表是固定且很小的。其他一切必须来自 -L 路径上的 .hbc，而那种形式用引号不用尖括号。", {"用内置模块：{available}", "或者按模块名链接你自己的归档：#link \"yourlib\";", nullptr}, "docs/LANGUAGE.md#2.7", {"spec", "available", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3002", "include 成环：{chain}", "include 是深度优先展开的，成环就永不终止 —— 编译器会反复重新打开同一个头文件。注意这是**模块**环，不是运行期环：打破它改变的是\"哪些声明可见\"，不是执行顺序。", {"把共用的声明挪进第三个头文件，两边都 include 它", "或者如果某个 include 只是为了一个可以前向声明的类型，删掉它", nullptr}, "docs/LANGUAGE.md#9.3", {"chain", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3003", "include 链深达 {depth} 层，超过上限 {limit}", "上限存在是为了让恶意或误写的链条耗尽不了栈。它远高于任何可读的设计 —— 真撞到上限，说明头文件层次有问题，不是上限有问题。", {"压平层次：把共用声明放进一个叶子头文件", "或者把最深的那个头拆成两个平级的，而不是嵌套的", nullptr}, "docs/LANGUAGE.md#9.3", {"depth", "limit", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3004", "本单元展开出 {count} 个模块，超过上限 {limit}", "每个模块都要解析并保留到编译结束。上限给恶意输入的内存定了界，也让\"这个构建要多久\"能从源码树本身回答。", {"拆分单元：把一部分挪到 #link 后面，那样它的模块不会被重新解析", "或者合并那些总是一起被 include 的小头文件", nullptr}, "docs/LANGUAGE.md#9.3", {"count", "limit", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3005", ".h 头文件里的 workflow 不能带函数体", "头文件只声明接口；头里写函数体会被复制进每个包含者，于是跑的是哪份实现取决于 include 图而非 #link。", {"把函数体挪到对应的 .hermes 实现里", "头文件只保留签名", nullptr}, "docs/LANGUAGE.md#9.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3009", "tool 声明字段必须是 name = \"value\"; 的形式", "工具元信息（端点、方法、幂等性）是一组扁平字符串字段；字段写坏就无法把工具描述给运行时。", {"每个字段写成 name = \"value\";", "确认值是用引号括起来的字符串字面量", nullptr}, "docs/LANGUAGE.md#3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3015", "#include {path} 指向的是实现文件；只能 include .h", ".hermes 里有函数体。include 它等于让每个包含者都拿到一份自己的实现副本，并把\"链的是哪份实现\"从 #link 手里挪到 include 图上 —— 而 #include/#link 分离存在的意义正是守住这个性质。", {"要用它的实现，写：#link \"{mod}\";", "只要它的类型，include 它的接口：#include \"{name}.h\"", nullptr}, "docs/LANGUAGE.md#2.7", {"path", "mod", "name", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3016", "tool.call 需要 #link <std/net>；model.generate 需要 #link <std/model>", "内置能力不是默认存在的：网络与模型原语只有在本单元链接了对应 stdlib 模块时才可用，未链接的调用没有实现。", {"tool.call 加 #link <std/net>;", "model.generate 加 #link <std/model>;", nullptr}, "docs/LANGUAGE.md#2.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3017", "#link 只允许出现在 .hermes 文件里", "#link 选择实现；头文件描述接口且会被多次包含，放在头里会把同一实现拉进每个包含者。", {"把 #link 挪进 .hermes 实现", "头文件里只保留 #include", nullptr}, "docs/LANGUAGE.md#9.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3018", "env() 的参数必须是常量字符串：插值不是常量", "后端端点或凭据名在构建期读取；插值出来的值要到运行期才知道，无法写进配置。", {"给 env() 传纯字符串字面量", "把插值挪到运行期代码里", nullptr}, "docs/LANGUAGE.md#8.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3019", "后端地址不能内嵌凭据（user:pass@host）", "URL 里的凭据会进日志、trace 和 IR；必须从 env() 来，才不会写进产物或泄漏。", {"从地址里去掉 user:pass@", "用 auth env(\"NAME\") 提供密钥", nullptr}, "docs/LANGUAGE.md#8.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3020", ".h 头文件里不能包含 backend 定义", "backend 定义含地址与密钥来源，属于实现而非接口；写进头文件会让每个包含者各得一份。", {"把 backend 定义挪到 .hermes 实现", "必要时头里只留声明", nullptr}, "docs/LANGUAGE.md#9.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3023", "input 参数必须带类型", "input 的类型就是请求契约；没有它，解码器没有 schema 去校验进来的 body。", {"标注类型：input: Req", "给该 struct 配上对应的 schema", nullptr}, "docs/LANGUAGE.md#4.8", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3026", "workflow 的形参只支持 \"input\" 与 \"backend\" 两种，其余不支持", "workflow 签名在本语言里是**链接期契约**，不是可调用接口：语言没有跨 workflow 调用，所以具名形参没有调用方，也就**没有任何取值来源**。宿主只提供一份 payload，那份 payload 就是 `input`；`backend` 则在编译期选后端。放行 `n: int` 的结果是\"编得过、永远跑不起来\"，而运行期那句报错的措辞像是编译器出了故障——把语言设计的缺口藏在编译器背后。", {"把值放进 `input` 的类型里，用 `input.<字段>` 读", "或者你本来是想选一个 backend，那就写 `backend = <已声明的 backend 名>`", nullptr}, "docs/LANGUAGE.md#3.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3030", "类型 {type} 不能跨 C ABI 边界", "只有 int、bool、string、double、cost 和不透明结构体在 C 里有稳定布局；json、vector<T>、泛型都没有", {"改用受支持的 C-ABI 类型：int、bool、string、double、cost 或不透明结构体", "把值包进结构体，以不透明指针跨边界", nullptr}, "docs/LANGUAGE.md#2.7", {"type", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3031", "extern 声明 {sym} 没有匹配的 #link native", "extern 符号的实现必须来自 #link native 指名的原生归档；缺它链接器无法解析该符号", {"在同一编译单元里加 '#link native \"<归档>\" from \"<头>\";'", "确认 extern 符号名与该归档导出的符号一致", nullptr}, "docs/LANGUAGE.md#2.7", {"sym", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3032", "原生头 {header} 不是纯 C ABI 头", "cgo 只解析 C；C++ 头（.hpp/.cpp/.cc）不能充当原生契约", {"为归档提供纯 C 头（.h）", "把 C++ API 包一层 extern \"C\" 薄封装，让 #link native 指向 .h 封装头", nullptr}, "docs/LANGUAGE.md#2.7", {"header", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3101", "一个编译单元只能包含一个 workflow（其余会被丢弃）", "汇编阶段围绕单个 workflow 构建 IR；多出的那个永远进不了产物，看起来却完全正常——数据被静默丢弃。", {"把每个 workflow 拆到各自的 .hermes 文件", "分别构建", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3102", "hermes compile: 裸机目标 {target} 没有动态加载器；--link-dynamic 被禁止（收到 \"{lib}\"）。改用 --link-static 加一份纯 C/Rust 的 .a。", "裸机产物就是固件：运行期没有加载器把 .so/.dylib 映射进地址空间，链接行里的动态库永远无法兑现。链接计划在裸机分支上刻意让 DynamicLibs 恒为空——放行一个的结果是产物链得过、起不来。", {"把 --link-dynamic 换成 --link-static，并给它一份纯 C/Rust 的 .a", "那个库只有 .so/.dylib 形态的话，先用 clang -c 加 ar rcs 重建成静态归档", nullptr}, "docs/LANGUAGE.md", {"target", "lib", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3103", "hermes compile: \"{lib}\" 带 Go runtime，但不在 g* 命名空间里。把它改名成 glibhermesnet.a（或 gnet.a），裸机闸门才看得见它；所有带 Go runtime 的库都必须以 'g' 开头。", "g* 前缀是一条**声明**，不是扫文件内容的启发式：编译器有权把每个 g* 库都当作带 Go runtime，而裸机闸门只读这条命名。不带前缀的 Go 归档对闸门是隐形的，于是它能走进固件——那时报的是缺 OS，而不是构建期的错。", {"把归档改名成 glibhermesnet.a（或 gnet.a）后重新生成链接计划", "如果它本来就是纯 C/Rust 库，就不要占用 g* 命名空间——两条边都是声明，不是扫描", nullptr}, "docs/C-ABI.md", {"lib", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3104", "hermes compile: 内置的 Go 网络归档是为宿主机构建的，无法链进交叉编译到 {target} 的产物。为 {target} 构建一份 g* c-archive 并用 --link-static 传进来，或者就在宿主机上原生编译本单元。", "Go c-archive 是宿主架构的机器码。把单元交叉编译到别的目标、却链宿主构建的归档，结果要么是 hermes_net_* 符号未解析，要么是架构不匹配——而链接器只会点一个符号名，离真正的原因很远。", {"按 {target} 的 GOOS/GOARCH 构建 g* c-archive，再用 --link-static 传进来", "或者去掉 --target，在这个单元将来运行的宿主上编译", nullptr}, "docs/C-ABI.md", {"target", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3105", "hermes compile: {flag} \"{lib}\" 是 C++ ABI 运行时（{stem}）。Hermes 只链纯 C ABI：名字修饰与 STL 布局跨编译器不可移植。请写一层 extern \"C\" 的 C 桥接并链它。", "名字修饰与 STL 内存布局都是编译器私有的，C++ ABI 运行时一旦进链接，产物就取决于那个库是谁编的。libc++ 在许可证上合法，但它仍然是一条 ABI 边界——所以这道检查和许可证闭集各管一条（许可证理由与 ABI 理由不能共用一个码）。受支持的路径是自己写一层 extern \"C\" 薄封装，它本身就是普通 C ABI 的 .a。", {"用 extern \"C\" 写一层薄桥接，编成普通 .a 再链", "只是要 C++ 标准库里的某个算法的话，自己实现或换一个纯 C 的库", nullptr}, "docs/C-ABI.md", {"flag", "lib", "stem", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3106", "hermes compile: 裸机目标 {target} 只能链静态 .a 归档；--link-static \"{lib}\" 不是静态归档。请把它重建成纯 C/Rust 的 .a。", "裸机分支里，链接计划只装你点名的静态归档——没有动态库、没有 framework、没有加载器。不是 .a 的路径（.so/.dylib、目标文件、目录）没有归档索引可供解析 hermes_net_* 或你的 extern 符号，于是链接报的是未解析符号，离真正的原因很远。", {"用 clang -c 加 ar rcs 重建成纯 C/Rust 的 .a", "或者把 --link-static 指向一个本来就以归档形式发布的等价库", nullptr}, "docs/LANGUAGE.md", {"target", "lib", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3107", "hermes compile: 本程序调用 tools/models，需要 Go 网络归档；用这条命令构建：go build -buildmode=c-archive -o build/glibhermesnet.a ./cmd/hermesnet", "tool.call / model.generate 在生成的 C 里降成 hermes_net_* 调用，而这些符号唯一的载体就是 Go 网络归档（内含 AI 接口兼容层的 c-archive）。一个归档都没解析到时，这些调用在链接期全是未解析符号。", {"跑消息里那条 go build；或者用 HERMES_NET_LIB 指向已有的 g* 归档（默认查找 build/glibhermesnet.a）", "本程序确实不需要网络或模型的话，去掉 tool.call / model.generate 和需要它们的 backend", nullptr}, "docs/C-ABI.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3108", "hermes compile: {bad} 是 {name} 运行时（{licence}）：{reason}（出处：{source}）", "许可证红线是一个闭集，在**计划面**上再查一次是纵深防御：--link-* 的输入在构造计划前已经过闸，但内置网络归档是另一条输入路径。命中意味着这份产物会静态带上一份许可证不允许分发的运行时。判据是\"哪个运行时进了链接\"，不是符号长什么样——名字修饰既会误报也会漏报。", {"改链一个许可证允许分发的等价实现", "读消息里 (source: …) 那个出处——每条规则自带权威链接，豁免条件就写在那里", nullptr}, "docs/LANGUAGE.md", {"bad", "name", "licence", "reason", "source", nullptr, nullptr, nullptr}},
  {"E3109", "[ERROR] Blocking synchronization or network routing requires a host OS.", "sleep 与 until 需要调度器和条件变量；定向 emit（route == 2，`to <ctx>`）需要一个活着的上下文句柄来路由。裸机上这两样都没有——槽表就是静态地址。频道路由（route == 1）**刻意不在这个集合里**：它是编译期哈希加一次整数比较，裸机上照样能做。", {"把 sleep/until 换成计数或轮询的循环——裸机上没有阻塞等待", "emit 改成频道路由（不带 `to <ctx>`），或者把这个 workflow 挪到宿主侧", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3110", "带 Go runtime 的库（g*）不能链进裸机目标。请改用纯 C/Rust 静态库。", "裸机产物运行时没有操作系统：没有调度器、线程、动态加载器和系统调用层。Go runtime 归档的机器码默认这些东西都存在，所以固件可能链得过、却在第一次 goroutine 切换时就死。g* 前缀是「这个库带 Go runtime」的声明（旧 Go 归档名也在筛查表里），所以链接计划按名字拒绝，而不是靠猜符号。", {"把网络层重建为纯 C/Rust 静态 .a，用 extern \"C\" 桥接暴露接口后链它", "或者去掉 --target，在宿主上原生编译本单元（宿主有 Go runtime）", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3111", "`--link-*` 的值不是本机可用的库文件", "`--link-static` / `--link-dynamic` 的契约是一个库**文件路径**，不是系统库名，也不是链接器选项。裸 `-l<名字>`、`-L<目录>`、`-Wl,...` 以及其他以 `-` 开头的值都会被原样转给链接器，于是链接计划从未见过的库也能进入产物；而静态 `.a` 不产生 `DT_NEEDED`，产物侧闸门根本查不到它。", {"传一个本机已存在的 `.a` / `.so` / `.so.N` / `.dylib` 文件", "或者如果编译器驱动本来就能找到这个库，去掉该旗标", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4120", "函数上的契约子句尚未支持（2.0.1）；workflow 上可用", "D-036 允许契约写在 workflow 或函数上。函数的体在每个调用点被内联，所以写在那里就必须在每个内联点展开——这部分还没实现。拒绝是**刻意**的：忽略子句等于悄悄丢掉作者写下的承诺。", {"把契约写到 workflow 上，或者在函数体里用 `if` 检查条件", "或者如果你确实需要函数级契约，把这个缺口记录下来", nullptr}, "docs/LANGUAGE.md#39-契约子句require--ensured036201", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4002", "这个 catch 不可达：前面的 catch (Error e) 已经能捕获一切", "catch 分支按顺序匹配；catch (Error) 放在更窄的分支之前会吞掉所有错误，后面的分支永远跑不到。", {"把宽的 catch (Error) 挪到最后", "或者删掉这个不可达的分支", nullptr}, "docs/LANGUAGE.md#5.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4005", "cost 不能与裸 int 相加或相减", "cost 是微美元；拿裸 int 去加等于默认那个 int 也是微美元，一个单位错误会把金额悄悄差 10^6 倍。", {"把 int 显式转成 cost", "或者全程用同一种单位", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4006", "int 与 double 不会自动提升", "没有隐式数值提升；int 到 double 的自动转换是静默精度损失与舍入 bug 的经典来源。", {"显式转换成你要的类型", "或者让两个操作数同类型", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4007", "算术运算符用在了非数值操作数上（string、bool、json）", "字符串没有算术，也没有运算符重载；拼接被刻意禁止因为它会掩盖编码与区域设置，一元负号只对数字有定义。", {"用字符串插值（把值写进字符串里）而不是运算符", "算术前把 json 收窄成数值类型（json.as_int）", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4008", "cost 与 double 不能在算术里混用", "cost 是整数微美元；与 double 混算会重新引入 cost 本想避免的舍入误差。", {"金额运算留在 cost（整数）里", "或显式转换并明确舍入", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4009", "运算符 % 需要 int 操作数", "取余只对整数有意义；对 cost、double、string、json 或 struct 取余没有良定义。", {"% 用 int 操作数", "对 cost 先换算成微美元整数", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4010", "不能用 == 或 != 比较两个不同类型的值", "相等要求两侧同类型；跨类型比较没有唯一含义，只能靠隐藏的强制转换。", {"比较同类型的值", "显式把一边转换成相同类型", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4011", "这些操作数类型不能做大小比较", "大小比较（< <= > >=）只对 int、double、cost、string 有定义；bool、json、struct 没有全序。", {"只比较 int、double、cost 或 string", "对 json，先取出具体字段再比", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4012", "逻辑 &&、||、! 需要 bool 操作数", "语言没有真值性；&&、||、! 是布尔联结词，int/string/json 操作数需要并不存在的非零即真隐式规则。", {"显式比较：x != 0，或 s != 空字符串字面量", "或者把操作数改成 bool", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4014", "同一文件里重复声明了同名 struct", "每个 struct 名对应一种布局；同文件里第二次声明会让类型二义，字段顺序取决于哪份胜出。", {"给其中一个改名", "若是残留，删掉重复的那份", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4016", "该类型没有这个字段", "字段访问按固定偏移读槽位；类型没声明的字段会读到从未布局的字节，因此无法编译。", {"使用该类型已声明的字段", "或者把该字段加进 struct 声明", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4018", "`match` 缺少 `default` 分支", "字符串主题无法证明穷尽，缺 default 的 match 遇到不匹配的值时结果未定义。", {"加一个 default: 分支", "或者收窄主题使各分支可证明穷尽", nullptr}, "docs/LANGUAGE.md#5.3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4019", "`case` 标签与 `match` 主题的类型不一致", "case 标签要跟主题比较；字符串主题配 int 标签（或反之）永远匹配不上，说明类型搞混了。", {"让标签与主题同类型", "或者在 match 前先转换主题", nullptr}, "docs/LANGUAGE.md#5.3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4020", "同一个 case 标签出现了多次", "重复标签让第二个分支成为死代码，也掩盖了作者本想写另一个值的事实。", {"删掉重复的分支", "或者改成你真正想要的值", nullptr}, "docs/LANGUAGE.md#5.3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4021", "返回类型不匹配：返回的值与声明的返回类型不符", "声明的返回类型是 workflow 的契约——调用方、链接器和 IR schema 都依赖它；返回别的类型会同时破坏三者。", {"返回声明类型的值", "或者把声明改成你实际返回的类型", nullptr}, "docs/LANGUAGE.md#3.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4022", "不能返回元组", "workflow 的返回类型必须是有 schema 的单一具名类型；元组没有名字，无法导出或描述给调用方。", {"把值包进 struct 再返回", "或者只返回一个值，其余通过 input 传", nullptr}, "docs/LANGUAGE.md#3.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4023", "不能把 error 对象绑定到变量", "catch 的 error 对象只活在它自己的 catch 块里且是借用的，不归你所有；绑出去会让它比所指向的错误活得更久。", {"在 catch 块内联使用 error 对象", "若之后要用它的数据，显式把字段拷出来", nullptr}, "docs/LANGUAGE.md#5.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4024", "`unlimited` 不是值：只能出现在 max_steps = unlimited 的位置", "`unlimited` 意为没有编译期上界，是上界标记而非常量；放进值位置会造出没有值的变量并破坏所有上界。", {"只在 model.agent(max_steps = unlimited) 里用 unlimited", "其他位置赋具体值", nullptr}, "docs/LANGUAGE.md#6.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4025", "fallback 的返回类型与主表达式不一致", "fallback 是主表达式抛错时采用的值；类型不同会让调用方在运行期拿到两种不兼容类型之一。", {"让 fallback 返回与主表达式相同的类型", "或者把 fallback 的值转换成该类型", nullptr}, "docs/LANGUAGE.md#5.4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4026", "不能在 fallback 块里重新赋值 const 变量", "const 在整个作用域内不可变；fallback 不是例外——在里面改会让 const 在不同块里含义不同。", {"需要可变就用非 const 变量", "或者把赋值移出 fallback", nullptr}, "docs/LANGUAGE.md#5.4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4027", "if/while 的条件必须是 bool", "条件是控制流分支点，语言没有真值性；int/string/json/cost 没有为真的概念，隐式规则在运行期是未定义的。", {"显式比较：x != 0，或 s != 空字符串字面量", "或者让表达式产出 bool", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4028", "在 `for` 循环结束后使用了循环变量", "循环变量归 for 头所有，只在循环体内存在；循环结束后槽位被回收，在外面引用就是读一个已经不存在的变量。", {"把使用挪进循环体", "或者在循环前声明一个变量把值存下来", nullptr}, "docs/LANGUAGE.md#3", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4029", "旧 float 标签在 IR 里没有表示", "这是旧标签的纵深防线，不是「所有浮点字面量被拒」。v2.0.0 起唯一浮点类型是 `double`（IEEE-754 binary64），字面量编成位模式 {{\"k\":\"double\",\"bits\":\"<16 位小写 hex>\"}}，IR 字节里没有 JSON 浮点数字，V-7 / canonical / 签名三件事都不受影响。带 \"float\" 标签的 LitExpr 是 v2.0.0 之前的形态：它会落进字符串兜底，产出 {{\"t\":\"string\",\"v\":\"float\"}} —— 合法 IR，运行期却静默返回字符串 \"float\"。三道扫描器保留下来，防的是忽略诊断直接调 C ABI 的宿主。", {"浮点用 `double`（字面量 1.5 / 1.5e2 / 1e3 都支持）", "金额仍留在 `cost` / int 微单位；`json.as_float` 这个 API 名保留原名", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4030", "调用实参类型不匹配", "实参类型与被调方声明的形参类型不同；没有隐式转换，调用无法按声明签名编译。", {"传声明形参类型的值", "或者显式转换实参", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4031", "数组下标必须是整数", "数组下标是整数偏移；非 int 下标没有确定位置，需要隐藏的截断。", {"用 int 下标", "或者把下标显式转成 int", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4032", "不能对非数组的值取下标", "只有数组支持按下标访问；对 int/string/json/struct 取下标没有元素可取。", {"对数组值取下标", "对 json，先取出类型化数组（json.as_array）", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4033", "不能用 == 或 != 比较两个 double", "二进制浮点的精确相等不是一个稳定谓词，编译期证不出来，所以直接拒，而不是让它静默返回 false。舍入会让两个数学上相等的值比出不相等，NaN 与自己也不相等：`x == x` 可能为假，而 `x != x` 悄悄成了语言里唯一的 NaN 判据。", {"把值保持在精确单位上（int 微单位或 `cost`）再比", "或者用显式容差比较：可以写 `double` 字面量，也可以取自输入（如 `json.as_float(input.eps)`）；相等比较本身仍然被拒", nullptr}, "docs/LANGUAGE.md#4.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4034", "该错误字段规范里有，但运行期还没有带上", "LANGUAGE.md 7.1.1 声明了这个字段，所以它不是拼写错误——但执行器的错误值目前还没有填它。放行的话会编得过、运行期死在 `field does not exist` 上，而那是普通 error，catch 接不住：静态检查通过而程序失败，比直接拒绝更坏。", {"改读运行期已经带上的字段（E4016 的 help 按错误类型列出了它们）", "或者把结果当正常值读：`allow_status = [404]` 时状态码从 HttpResult<T> 回来，`r.status == 404` 根本不需要错误对象", nullptr}, "docs/LANGUAGE.md#7.1.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4035", "backend 参数的默认值必须是裸 backend 名", "形参的默认值会变成 `params[].v`——一个**编译期折叠好**的常量，所以 `backend = 1 + 1` 没有任何值可记，运行期也没有求值器去算它。而\"用哪个 backend\"**只**从裸标识符取：`backend = \"homonoia\"` 会折成 {{\"k\":\"string\",\"v\":\"homonoia\"}}，却仍然留下一个**空的 backend 名**，于是用户接下来看到的是另一条毫不相干的报错。点号路径更糟——它会被折成**最后一段**，静默选中另一个 backend。", {"把 backend 名裸写、不加引号：`backend = homonoia`", "或者干脆不写这个形参：没有它就意味着这个 workflow 没有默认 backend", nullptr}, "docs/LANGUAGE.md#3.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3027", "#bind 只能出现在 .hermes 文件里", "#bind 说明的是**谁提供实现**。.h 只描述「长什么样」，从不决定「由谁实现」：写进头文件会让每个 include 它的单元继承一个它没做过的实现选择，同一个类型在不同单元里解析到不同供给方。", {"把 #bind 移到对应的 .hermes 里", ".h 里只留声明（struct / extern / workflow 签名）", nullptr}, "docs/LANGUAGE.md#3.5", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E3028", "#bind 必须写在文件顶层", "指令不是语句。#bind 决定整个 unit 链接到哪个实现，必须在任何函数体之前确定——写在 workflow 或函数体里，它连「作用于哪个模块」都没有边界。", {"把 #bind 移到文件开头，在所有 workflow / 函数之前", "或者从体内删掉它：函数体不能自己选供给方", nullptr}, "docs/LANGUAGE.md#2.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4036", "#bind 不引入名字：{name} 未声明", "#bind 决定的是**谁提供实现**，不是**你能看见哪些名字**。这是两个问题，Hermes 拒绝把它们捆在一根字符串上：供给方那条边带身份和哈希，而可见性由 #include 带进来。", {"补上声明它的 include：#include \"{header}\"", "或者在某个 .h 里写出完整声明，再 include 那个头", nullptr}, "docs/LANGUAGE.md#3.5", {"name", "header", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4101", "void 调用不能当值使用", "`void` 的意思是这次调用什么都不返回：既没有值可存、可传，也没有值可比，所以值位置（绑定的右值、实参、运算符的一侧）根本无处安放。放行它会在 IR 装配期留下一个洞，而那时的报错点的是一个缺失的节点字段，不是\"这次调用不返回值\"。", {"把这行改成独立语句，去掉绑定", "确实需要它产出值时，给被调方一个返回类型——`void` 只能当语句，不能当操作数", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4102", "{fn} 接受的是 snapshot，实际传入 {got}", "snapshot 是 memory.checkpoint() 返回的**不透明**句柄：它是事务边界，不是一个值。其他任何东西（json 值、int、struct）都不是边界，对它提交只会静默什么都不做。Snapshot 刻意做成独立类型而不是 json：它进不了 json，也不能跨 workflow 传递。", {"传 memory.checkpoint() 拿到的那个值", "把句柄存在局部变量里，跨 checkpoint() 与 rollback()/commit() 使用——它不透明，存不进 json，也交不给别的 workflow", nullptr}, "docs/LANGUAGE.md", {"fn", "got", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4103", "void 调用不能作为返回值", "返回一个 `void` 等于把一个不存在的值交给调用方。声明的返回类型是这个 workflow 的契约，返回位上没有东西可写。", {"把这行调用单独成句", "然后 `return` 一个声明类型的值", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4104", "这个 workflow 必须返回值", "声明的返回类型不是 void，于是裸写 `return;` 会让出口缺一个值，后端会发出一个结果未定义的 `ret`。workflow 体内的 `return` 就是调用方拿到的那个值。", {"返回一个声明类型的值", "或者把 workflow 的返回类型声明成 void，并把其他每个 `return` 的值一并去掉", nullptr}, "docs/LANGUAGE.md#4.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4105", "break 不在循环里", "`break` 跳出的是最内层循环，而类型检查只把 for/while 的循环体算作循环——这里没有可跳出的东西。跨越 workflow 边界是 `stop` 的职责，两者混用会让控制流读不懂。", {"要提前结束 workflow，用 `workflow.stop(reason: …)`", "或者把这条 `break` 挪进它想跳出的那个循环", nullptr}, "docs/LANGUAGE.md#3.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4106", "continue 不在循环里", "`continue` 跳的是最内层循环的下一次迭代。外面没有循环就没有目标，这条语句只会看起来像控制流，实际什么都不做。", {"把它挪进它想继续的那个循环", "或者删掉——这里没有任何东西可以被继续", nullptr}, "docs/LANGUAGE.md#3.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4107", "stop 不在 workflow 体内", "`stop` 结束的是当前 workflow，并把它的 data 写进返回位。声明层没有 workflow 可结束：类型检查只在 workflow 体内进入该状态。", {"把它挪进 workflow 体", "如果这是顶层初始化，那没有东西可停止——删掉", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4108", "stop 的 data 与 workflow 的返回类型不符", "`workflow.stop` 会把 data 返回给调用方，所以 data 必须是 workflow 声明的那个类型。stop 直接写进返回位，类型不对就是一个类型错误的 `ret`：编得过，调用方读到的是垃圾。", {"传一个声明返回类型的值", "或者把 workflow 的返回类型改成你实际传的那个类型", nullptr}, "docs/LANGUAGE.md#3.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4109", "未声明的信号 `{sig}`", "信号是一个闭集，用 `export signal <Name>;` 声明。同一个码由三处共发，措辞分别是 `handler for undeclared signal`、`wait for undeclared signal`、`emit of undeclared signal`——因为它们说的是同一件事：这个名字不在已声明的集合里，只可能是拼错。给它绑 handler 会永远等下去，等它会每次都等到超时，emit 它则打进空气里，什么也不报。", {"用 `export signal <Name>;` 声明它", "或者检查拼写——名字必须与已声明的信号逐字相同", nullptr}, "docs/LANGUAGE.md", {"sig", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4110", "同一作用域里 `{sig}` 有两个 handler", "handler 是按作用域收集的。同一个信号在同一个作用域里有两个，两者都是候选，而跑哪个由绑定顺序决定——那不是读者看得见的东西，程序行为就依赖了一个隐形的次序。", {"把两个 handler 合并成一个", "或者把其中一个挪进嵌套块——表是按作用域算的，嵌套作用域可以自己再声明一个", nullptr}, "docs/LANGUAGE.md", {"sig", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E4111", "sleep 需要一个时长", "时长是毫秒数，或带单位的字面量（parser 已经折算好）；其他类型对运行期没有意义，只会被静默转换。同一个码也用于 `until` 的 `timeout takes milliseconds as an int`：timeout 与单调时钟按毫秒比较，字符串或 struct 当不了截止时间。", {"传 int（毫秒）或带单位的字面量，如 sleep(1500) 或 sleep(1.5s)", "timeout 位传 int 毫秒：timeout(30000) 或 timeout(30s)", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E5002", "在 `parallel` 块内声明的值在块外不可见", "parallel 的每个分支并发执行；块内产生的值在块外没有唯一确定的值，因此作用域限于块内。", {"在 parallel 块内使用该值", "或者从分支返回再合并结果", nullptr}, "docs/LANGUAGE.md#5.2", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E5007", "`retry` 内的工具调用没有幂等证明", "retry 在遇到 RunError 时重跑整个 body；未证明幂等的 call_tool 会把同一个 POST 再发一遍——重复扣款、重复副作用。", {"把该调用移出 retry 子树", "或者给工具真证明（GET/HEAD、idempotent = true，或纯 idem_key）", nullptr}, "docs/LANGUAGE.md#5.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E5009", "幂等键必须由输入派生", "常量或随机的 idem 键并不幂等：常量会把不同请求塌缩成一个，随机键每次重试都变，等于没去重。", {"用请求字段派生键（如订单号）", "或者工具本就幂等，索性省掉 idem_key", nullptr}, "docs/LANGUAGE.md#5.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E5010", "不能在 `parallel` 内写外部变量", "parallel 分支并发执行；写块外声明的变量是数据竞争，结果取决于调度，因此被拒。", {"每个分支返回值，parallel 之后再合并", "或者用分支内声明的变量", nullptr}, "docs/LANGUAGE.md#5.2", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_ASSIGN_IMMUTABLE", "不能修改 const 变量", "`decl` 节点带 const:true（IR.md §4.2）表示这个绑定永不改变；只有 `auto` 声明的变量可以被赋值。这条在**装配期**判，不在运行期：晚判意味着错误的程序能编过，只在跑到那一行时才失败。它是少数几条用户真能自己修的加载期诊断，所以汇编阶段把它报成用户错误，而不是编译器 bug。", {"去掉 `const`，或者改成给一个新变量赋值", "如果这份 IR 不是 `hermes ir` 产出的，重新生成一份——const 的 `decl` 后面跟着一条指向它的 `assign`，只可能来自手改", nullptr}, "docs/IR.md#4.2", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_BAD_LOC", "{what}：loc.m={m}，但 unit 只有 {count} 个模块（0..{last}）", "loc.m 是 unit.modules[] 的下标。越界会让**诊断渲染器自己崩掉** —— 加载器在试图报告一个失败时失败，你看到的会是 panic 而不是这条消息。", {"修产生方的 loc.m —— 这几乎总是前端 bug，不是手改 IR", "如果是手工编辑过的 IR，重新生成一份", nullptr}, "docs/LANGUAGE.md", {"what", "m", "count", "last", nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_BAD_ROOT", "workflow {wf}：root={root}，但 {reason}", "执行器从 root 开始，并在那里期待一个语句列表，也就是 k=\"seq\" 的节点。其他 kind 没有定义好的入口语义，跑起来第一步就是未定义行为。", {"把 root 指向第一个 `seq` 节点", "或者如果 workflow 只有一条语句，把它包进一个 `seq` 节点", nullptr}, "docs/LANGUAGE.md", {"wf", "root", "reason", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_CODEGEN", "代码生成失败：该 workflow 无法降到 IR", "codegen 会拒绝无法忠实下降的形状（如形状不符的 if/return 决策树）；产出错误的 IR 比失败更糟。", {"修正消息点名的那处构造", "或者上报——内部 codegen 错误是编译器 bug，不是你的输入", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_CYCLE", "workflow {wf} 的节点图有环 —— {chain}", "IR 必须是有向无环图（IR.md V-3）。有环意味着执行器可以永远重新进入同一个节点，于是超时和预算都兜不住 —— 它只能被外部杀掉，而不是自己停下来。", {"删掉 {edge} 这条边来打破环", "如果要重复执行，用 `retry` —— 它是有界的，而图本身必须无环", nullptr}, "docs/LANGUAGE.md", {"wf", "chain", "edge", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_DANGLING_REF", "{what} 指向 {id}，但 {table} 只有 {range}", "IR 里每个引用位置上的 id 都必须落在它所指的那张表内。悬空意味着这份 IR 被截断过、被手改过，或者产它的前端差了一个版本。", {"删掉 {path} 处的这个引用", "或者补上缺失的条目 —— 表必须与它的引用保持一致", nullptr}, "docs/LANGUAGE.md", {"what", "id", "table", "range", "path", nullptr, nullptr, nullptr}},
  {"E_IR_DUP_ID", "workflow {wf} 里 node id {id} 重复：先出现在 {first}，又出现在 {second}", "node id 就是数组下标（IR.md §4）。两个节点共用一个 id 会让所有指向它的引用变成二义 —— 一个声称指向 {id} 的 kid 到底指哪一个，取决于遍历顺序。", {"把 {second} 处的节点重新编号（id 必须连续，0..{last}）", "或者删掉两个里的一个（如果是残留的话）", nullptr}, "docs/LANGUAGE.md", {"id", "wf", "first", "second", "last", nullptr, nullptr, nullptr}},
  {"E_IR_DYNAMIC_CALL", "非递归函数 {fn} 在 {where} 处通过 call_fn 调用：编译模式必须把它展开", "Hermes 是编译型语言：非递归函数在编译期展开，运行期没有动态派发。指向非递归函数的 call_fn 说明 IR 来自旧编译器、被手改过，或者 codegen 有 bug。放行它等于在上界本该静态的地方悄悄恢复动态派发。", {"用当前编译器重新生成 IR（非递归调用会被内联）", "如果 {fn} 确实递归，把它标成 recursive —— 深度上限 512 是唯一的运行期闸", nullptr}, "docs/LANGUAGE.md", {"fn", "where", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_ENTRY", "{reason}（workflow {name}）", "入口选择必须唯一：不带 --workflow 的 `hermes run` 会选唯一的那个导出入口。零个候选意味着没东西可跑；两个意味着选择是抛硬币，产物不可重现。", {"给恰好一个导出的 workflow 打上 `entry`", "或者在运行时显式传 --workflow <name>", nullptr}, "docs/LANGUAGE.md", {"reason", "name", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_EXPORT_MISMATCH", "workflow {name} 的 exported={exported}，但 {where} {verb} 它", "workflow 上的 `exported` 和 exports.workflows（符号表）是同一个事实的两份表示。剥离器读标量，链接器读符号表。两者不一致时，一边认为符号可达、另一边认为它不存在 —— 于是产物能不能用取决于哪个工具先跑。", {"把 workflow 的 exported 设为 {want}", "或者 {action} \"{name}\" {target}", nullptr}, "docs/LANGUAGE.md", {"name", "exported", "where", "verb", "want", "action", "target", nullptr}},
  {"E_IR_FLOAT", "IR 在 {path} 处出现浮点 JSON 数字（开头是 {preview}）", "canonical JSON 禁止浮点（IR.md P-1）。浮点的最短往返表示在 Go / Rust / C++ 之间有真实分歧，只要它落进被哈希的字节里，跨语言校验就会随机失败，而且只在某些机器上失败。", {"编码成字符串：{{\"k\":\"double\",\"bits\":\"3ff8000000000000\"}}", "金额与概率用整数 —— 微美元（1e-6）和基点（1e-4）", nullptr}, "docs/LANGUAGE.md", {"path", "preview", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_LOAD_FAILED", "IR 字节不是本 schema 期望的合法 JSON：{detail}", "加载器按固定形状解码。某个字段的 JSON 类型不对时（该是整数的地方给了对象、该是列表的地方给了字符串），解码会在第一处不匹配处停下，之后的内容一概不检查 —— 所以在修好它之前你只会看到这一条。", {"修报出来的那个字段；周围的内容大概率是好的", "如果这份产物是手改的，重新生成一份", nullptr}, "docs/LANGUAGE.md", {"detail", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_RECOMPUTE_DRIFT", "{field} 声称 {claimed}，但从 IR 复算得到 {actual}", "这个字段是派生的，不是权威值。它在构建时写入、必须在加载时复算 —— 否则一个被篡改的值就能悄悄抬高执行上限，而 bounds 存在的意义恰恰是封住一次运行能做什么。", {"重新生成产物 —— 产生方写了不一致的值", "如果是手改的：不要改，派生字段是复算出来的，不是信来的", nullptr}, "docs/LANGUAGE.md", {"field", "claimed", "actual", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_RETRY_UNPROVEN", "retry 节点 {retry} 会把 call_tool {call} 执行多次，但工具 {tool} 的 idem.mode={mode} —— 没有任何幂等证明", "retry 在遇到 RunError 时会重跑整个 body。如果 body 里有未证明幂等的工具调用，每一次 5xx 都会把同一个 POST 再发一遍：重复扣款、重复副作用。E5007 是源码 AST 上的编译期闸门，保护不了被手改过的、旧编译器产出的、或被 codegen bug 搬过位置的 IR 文件。这条校验在加载期落在节点图上 ——「retry 内」的准确含义是「从 retry.body 可达」。", {"把 call_tool {call} 移出 retry 子树，只把已证明幂等的调用留在里面", "给 {tool} 一个真证明（GET/HEAD、idempotent = true 或纯 idem_key），用 hermes ir 重新生成 IR；不要手改 idem.mode", nullptr}, "docs/LANGUAGE.md", {"retry", "call", "tool", "mode", nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_SCHEMA_UNSTABLE", "{path} 处的 schema 重新 canonical 化后字节不同：{detail}", "schemas[].json 是原样嵌入的，并参与类型哈希。只要重编码改了一个字节，离线构建与验签就会对\"签的是哪份 schema\"产生分歧。", {"按字节序输出键、不留空白", "或者报告产它的前端 —— 这一般是 codegen 的 bug", nullptr}, "docs/LANGUAGE.md", {"path", "detail", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_SYM_CONFLICT", "符号 {name} 在 {namespace} 里出现 {count} 次：{places}", "四个命名空间（type / workflow / backend / tool）各自必须名称唯一。有重复时导出查找就依赖顺序 —— 链接器解析它先扫到的那个，于是同一份归档在两台机器上可能链出不同结果。", {"把其中一个改名", "或者如果是残留，删掉重复的导出", nullptr}, "docs/LANGUAGE.md", {"name", "count", "namespace", "places", nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_VAR_MISMATCH", "变量 {name}（id {var}）与绑定它的 `decl` 节点不一致：{detail}", "vars[] 和 decl 节点是同一个绑定的两种视图。执行器按 vars[] 预留槽位、在 decl 节点里赋值；两者不一致时，变量会从一个从没被写过的槽里读出来。", {"让 var {var}.decl 指向给它赋值的那个 `decl` 节点", "或者如果 decl 节点已经不存在，删掉这条 vars[] 记录", nullptr}, "docs/LANGUAGE.md", {"name", "var", "detail", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"E_IR_VERSION", "{field} 是 {got}，但本版本只接受 {want}（Hermes 2.0.0 及之后）", "IR 有意不做向前兼容：2.x 只读 2.0.0 及之后产出的东西。接受更旧的产物，等于按现在的含义去解释语义已经变过的字段 —— 一个看起来像正确答案的错误答案。没有迁移路径是有意的：1.x 的产物被明确拒绝，而不是被静默误读。", {"用这个编译器（2.0.0+）重新编译源码", "确实要跑 1.x 产物的话，用 1.x 的二进制 —— 不要手改版本字段", nullptr}, "docs/LANGUAGE.md", {"field", "got", "want", nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W2003", "#link 不需要结尾分号（和 #include 一样）", "指令不是语句：#include 和 #link 都止于行末，结尾多出的 ';' 是多余的。", {"去掉结尾的 ';'", "指令保持 #link <std/net>", nullptr}, "docs/LANGUAGE.md#2.7", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W2004", "max_steps = unlimited：该 agent 的步数没有静态可证的上界", "步数无限时 max_spans 不再是可证的 trace 上界、预算无法预留，只剩运行期硬上限。", {"需要可证上界就设具体 max_steps", "只有当你本就以运行期上限为闸时才接受它", nullptr}, "docs/LANGUAGE.md#6.4", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W4112", "信号 `{sig}` 在频道 \"{chan}\" 上没有任何 handler", "频道在编译期被哈希，拼错一个字符就得到一个没人监听的哈希：emit 照常执行，静默地什么都不做。全局 emit 匹配任意全局槽，而频道路由的 emit 只匹配同频道上的槽。", {"检查频道名，或者补一个 handler：on {sig} from \"{chan}\" {{ … }}", "如果它本来就由另一个模块处理，忽略这条警告。", nullptr}, "docs/LANGUAGE.md", {"sig", "chan", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W4113", "没有 timeout 的 until 可以永久阻塞", "workflow 的上界是步数，不是墙上时间。没有 timeout 的 until 没有任何编译器看得见的上界，于是少一次 emit 就能把这个产物挂死，而成本模型照样报一个有限的运行。", {"加个界：until(<Signal>) timeout(30s)", "如果这次等待本来就该无界，那就留着，但要保证 emit 一定会来。", nullptr}, "docs/LANGUAGE.md", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W5004", "拿形如状态码的 struct 字段去比 HTTP 状态码，但默认 tool.call 契约下非 2xx 根本不会绑定它", "没有 allow_status 时，tool.call 成功才返回 T，否则抛 HttpError —— 404 时执行流在 tool.call 那行就跳走了，字段从未被绑定，这个比较永远不可能为真。HTTP 状态只有通过 allow_status（HttpResult<T>.status）才到得了调用点。这是**启发式警告**不是错误：业务字段恰好叫 status 且真的等于 404 是合法的，编译器分不出这两种情况（LANGUAGE.md 12.1 L3）。", {"把该码写进调用的 allow_status，再比结果的状态：`tool.call<T>(..., allow_status = [404])` 然后 `r.status == 404`", "或者从响应体判断：200 响应才带 T，所以检查 T 上的业务字段（如 `found = false`），而不是 HTTP 状态码", nullptr}, "docs/LANGUAGE.md#12.1", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W5005", "入口没有结构契约：input 被声明为 json，hermes serve 无法据此生成文档，也无法在入口挡住畸形请求", "input 的类型就是 HTTP 请求契约。声明为 json 时请求体是任意 JSON，serve 既生成不出 API schema，也无法在入口校验字段。这是规范允许的逃逸口（LANGUAGE.md §4.8），但会失去编译期契约保护。", {"声明一个 struct 作为契约：input: SupportInput，其中字段即为请求体形状，非 T? 字段会被纳入 required", "若确实需要任意 JSON，保留 json 但接受此警告；也可使用 --deny-warnings 将其升级为错误", nullptr}, "docs/LANGUAGE.md#4.8", {nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
  {"W_IR_PANEL_TRUNCATED", "在 {shown} 条诊断后停止；另有 {dropped} 条被抑制", "一份坏输入可以产生上千条连带的错误，而有用的永远在最上面。上限让报告保持可读，也给恶意 IR 的产出的内存定了界。", {"先修前 {shown} 条再重跑 —— 其余通常是连带结果", "确实想看全量的话用 --max-diags 提高上限", nullptr}, "docs/LANGUAGE.md", {"shown", "dropped", nullptr, nullptr, nullptr, nullptr, nullptr, nullptr}},
};
