const DiagCatalogEntry* diag_catalog_find(const char* code, bool zh) {
  if (code == nullptr) return nullptr;
  const DiagCatalogEntry* table = zh ? kDiagCatalogZH : kDiagCatalogEN;
  const size_t n = zh ? kDiagCatalogZHCount : kDiagCatalogENCount;
  for (size_t i = 0; i < n; ++i) {
    if (strcmp(table[i].code, code) == 0) return &table[i];
  }
  return nullptr;
}

